import{_ as l,l as n,o as e,c as o,v as i,p as s,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Circuit Tracing 电路追踪","description":"","frontmatter":{"title":"Circuit Tracing 电路追踪","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/circuit-tracing.md","filePath":"llm/circuit-tracing.md","lastUpdated":1789023840000}'),E={name:"llm/circuit-tracing.md"};function h(u,a,m,A,g,B){const t=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="circuit-tracing-电路追踪" tabindex="-1">Circuit Tracing 电路追踪 <a class="header-anchor" href="#circuit-tracing-电路追踪" aria-label="Permalink to &quot;Circuit Tracing 电路追踪&quot;">​</a></h1><div class="epigraph"><p>我们用一种方法揭示语言模型行为背后的机制：在替换模型里逐步追踪计算，为感兴趣的提示生成图描述。</p><footer>—— Ameisen, Lindsey, Pearce, Gurnee, Turner et al., Circuit Tracing: Revealing Computational Graphs in Language Models, Transformer Circuits Thread, 2025-03-27</footer></div><p>电路追踪（circuit tracing）是 Anthropic 在 2025 年公开的一套方法，用来把一次前向拆成可可视化、可干预的计算图。它不是某一类注意力头的名字，而是一条流水线：训练更可解释的替换组件、在替换模型上归因、剪枝成图、再用夹持实验验证。配套的生物学论文把同一套工具打到 Claude 3.5 Haiku 上，展示多步推理、语言混合、诗歌与拒答等行为的内部路径。归因图是这条流水线的产物；本篇写流水线本身，以及它相对手工电路分析的取舍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工电路分析在 GPT-2 small 的 IOI 任务上证明了可行性，却难以搬到前沿模型。障碍有三。MLP 神经元多义，几乎不能当节点；注意力头在大模型里功能混杂；搜索空间随层数与宽度组合爆炸。稀疏自编码器改善了「方向可命名」，但默认只解释残差里有什么，不解释这些方向怎样一步步写成输出。</p><p>电路追踪要的是可扩展的机制发现：对任意感兴趣的提示，自动提出「中间步骤假设」，并提供验证接口。它承认不能无损还原原模型，于是显式引入替换模型，把不可解释的 MLP 换成稀疏特征计算，在可解释的代理上做追踪。</p><h3 id="为何必须替换而不是只读原-mlp" tabindex="-1">为何必须替换而不是只读原 MLP <a class="header-anchor" href="#为何必须替换而不是只读原-mlp" aria-label="Permalink to &quot;为何必须替换而不是只读原 MLP&quot;">​</a></h3><p>原 MLP 是稠密非线性，特征叠加（superposition）让单个神经元没有稳定语义。转码器或交叉层转码器学习用稀疏潜变量重建残差更新，潜变量更接近「一个方向一个概念」。追踪发生在这个代理里。代价是代理误差：凡是重建不好的计算，都会逃出特征账本。方法论文把误差做成一等公民，而不是事后道歉。</p><p><span class="marginnote">电路追踪与 Meng 等人的因果追踪同名不同物。后者在原模型激活上做修补，定位哪一层、哪个 token 位置介导了事实回忆。前者先换掉 MLP，再在特征图上走归因。两者都是干预式解释，但对象分别是位置/层与稀疏特征通路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线分四段。</p><p>第一，训练交叉层转码器，使一组稀疏特征能够解释多层 MLP 的输出。跨层是为了让同一概念不必被复制进每一层的字典。第二，对目标提示运行替换模型，记录活跃特征、残差、注意力输出与重建误差。第三，以目标 logit（或 logit 差）为根，计算节点间线性效应，得到归因图，再按贡献剪枝。第四，根据图提出机制假设，用特征夹持、消融、或把特征激活到对照提示的值，看输出是否按预言变化。</p><h3 id="验证工具与可视化" tabindex="-1">验证工具与可视化 <a class="header-anchor" href="#验证工具与可视化" aria-label="Permalink to &quot;验证工具与可视化&quot;">​</a></h3><p>方法论文配套了交互式可视化：按贡献排序的边、按位置展开的特征、误差占比。验证不是看图讲故事，而是做扰动。若图说某特征是「计划输出首都」的中介，把它压到零，首都应掉；把它升到对照值，输出应偏向对照。Lindsey 等人在 Haiku 上对多类行为重复这一循环。后续 Kamath 等人补上注意力 QK 归因，使「为何看那个上下文位置」也能进入同一套追踪。</p><p>这套工具对 18 层研究模型先跑通，再应用到生产级 Haiku。顺序本身说明：追踪依赖替换质量，替换质量依赖能训得动的转码器；前沿模型不是从零手工找头，而是先有字典再有图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>追踪能成立，靠的是局部线性化。替换模型在给定激活模式附近是分段线性的，于是从输出反推的一阶贡献可加。稀疏性保证同时亮的特征不多，图才剪得动。交叉层则让「同一特征在不同层被读」显示为跨层边，而不是被误认成许多无关神经元。</p><h3 id="假设-干预闭环" tabindex="-1">假设-干预闭环 <a class="header-anchor" href="#假设-干预闭环" aria-label="Permalink to &quot;假设-干预闭环&quot;">​</a></h3><p>图上的路径是相关结构。闭环把它升级成因果声明：干预特征 \\(\\rightarrow\\) 下游特征与 logits 按边的符号移动。失败模式很具体。干预有效但图上没有对应边，说明线性化漏了通路；图上有边但干预无效，说明边是相关不是介导。生物学论文里多次出现并行路径与「内部冲突」（例如同时激活助答与拒答特征），这正是闭环要暴露的：模型不是单一故事线。</p><p><span class="marginnote">替换模型上的因果，不等于原模型上的因果。夹持的是转码器特征，不是原 MLP 神经元。若要把结论迁回原模型，应用等价的残差方向做修补，看行为是否同向。两套干预不一致时，应报替换误差，而不是只信图。</span></p><p>与早期 Circuits 工作相比，追踪降低了对「找到一组固定头」的依赖，改成「每次前向生成一张图」。代价是机制的单位变成特征字典里的编号，跨模型、跨训练检查点难以对齐。可扩展性换来了可移植性的损失。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>电路追踪的计算成本高：转码器训练、逐提示归因、交互式剪枝。它目前适合案例研究，不适合对每次用户请求做在线解释。字典完备性是硬上限——没有的特征不会出现在图上，只会漏进误差节点。长上下文、工具调用、多轮对话会让图爆炸，现有演示以短文本行为为主。</p><p>安全与政策解读尤其要克制。图上出现「欺骗」或「拒答」相关特征，只说明这次前向用了这些方向，不能外推成稳定意图。正确用法是：追踪提供可证伪的内部故事，故事必须在原模型干预与行为评测上站住。</p><p><span class="marginnote">不要把电路追踪理解成自动反向工程。自动的是图的生成；命名、合并同义特征、判断是否算「同一算法」，仍然是人在做。工具加速的是假设吞吐，不是把解释责任交给模型自己。</span></p>',25)),(e(),s(d,null,{default:r(()=>[p(t,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20Orig%5B%22%E5%8E%9F%E6%A8%A1%E5%9E%8B%20MLP%22%5D%20--%3E%20CLT%5B%22%E4%BA%A4%E5%8F%89%E5%B1%82%E8%BD%AC%E7%A0%81%E5%99%A8%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20CLT%20--%3E%20Fwd%5B%22%E6%9B%BF%E6%8D%A2%E6%A8%A1%E5%9E%8B%E5%89%8D%E5%90%91%22%5D%0A%20%20Fwd%20--%3E%20Graph%5B%22%E5%BD%92%E5%9B%A0%E5%9B%BE%20%2B%20%E5%89%AA%E6%9E%9D%22%5D%0A%20%20Graph%20--%3E%20Hyp%5B%22%E6%9C%BA%E5%88%B6%E5%81%87%E8%AE%BE%22%5D%0A%20%20Hyp%20--%3E%20Clamp%5B%22%E7%89%B9%E5%BE%81%E5%A4%B9%E6%8C%81%20%2F%20%E6%B6%88%E8%9E%8D%22%5D%0A%20%20Clamp%20--%3E%20Val%5B%22%E8%A1%8C%E4%B8%BA%E6%98%AF%E5%90%A6%E7%AC%A6%E5%90%88%E9%A2%84%E8%A8%80%22%5D%0A%20%20Val%20--%3E%7C%E5%90%A6%7C%20Graph%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>电路追踪是「替换模型 + 归因图 + 干预验证」的流水线，用来为单条提示生成可检验的机制假设。</li><li>交叉层转码器把 MLP 换成稀疏特征计算；重建误差必须进入追踪，不能丢掉。</li><li>验证靠夹持与消融，而不是靠可视化叙事；图与干预不一致时以干预与误差报告为准。</li><li>它补上了 SAE「有特征无通路」的缺口，但机制绑定字典，跨检查点对齐困难。</li><li>与激活修补式因果追踪互补：一个定位层与位置，一个定位特征通路。</li><li>出处：Ameisen et al., <em>Circuit Tracing: Revealing Computational Graphs in Language Models</em>, Transformer Circuits, 2025；Lindsey et al., <em>On the Biology of a Large Language Model</em>, 2025。</li></ul>',2))])}const T=l(E,[["render",h]]);export{C as __pageData,T as default};
